fn where_fn(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // We assume `condition`, `x`, and `y` all have the same length.
    // You can uncomment the asserts below if you want to enforce it at runtime.
    //
    // assert_eq!(condition.len(), x.len(), "condition and x have different lengths");
    // assert_eq!(condition.len(), y.len(), "condition and y have different lengths");

    condition
        .into_iter()
        .zip(x.into_iter())
        .zip(y.into_iter())
        .map(|((cond, xi), yi)| if cond { xi } else { yi })
        .collect()
}

